// One watchlist source in, one ingest payload out.
const src = $('Split Sources').item.json;
const res = $input.item.json || {};
const kw = (src.keywords || []).map(k => String(k).toLowerCase().trim()).filter(Boolean);

// Greenhouse returns its description as entity-encoded HTML: the body arrives
// as `&lt;div&gt;`, so it must be decoded before it can be stripped, and
// decoded again afterwards to finish the text inside the tags.
function decode(s) {
  return String(s).replace(/&(?:amp|lt|gt|quot|apos|nbsp|rsquo|lsquo|rdquo|ldquo|mdash|ndash|hellip|bull|#x?[0-9a-fA-F]+);/g, (m) => {
    const map = { '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&apos;': "'", '&nbsp;': ' ', '&rsquo;': '\u2019', '&lsquo;': '\u2018', '&rdquo;': '\u201d', '&ldquo;': '\u201c', '&mdash;': '\u2014', '&ndash;': '\u2013', '&hellip;': '\u2026', '&bull;': '\u2022' };
    if (map[m]) return map[m];
    const n = m.match(/^&#(x?)([0-9a-fA-F]+);$/);
    if (!n) return m;
    const code = parseInt(n[2], n[1] ? 16 : 10);
    if (!Number.isFinite(code) || code < 0 || code > 0x10ffff) return m;
    if (code >= 0xd800 && code <= 0xdfff) return m;
    return String.fromCodePoint(code);
  });
}
function strip(html) {
  return decode(decode(String(html || ''))
    .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<\/(p|div|li|h[1-6]|tr)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ''))
    .replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

// A board token that does not exist is a 404 with a JSON body, not a throw —
// the HTTP node is set to never error so one dead board cannot end the run.
if (!Array.isArray(res.jobs)) {
  const reason = res.error || res.message || `Greenhouse returned no job list for "${src.target}"`;
  return { json: { sourceId: src.id, label: src.label, error: String(reason).slice(0, 500), jobs: [] } };
}

const jobs = [];
for (const j of res.jobs) {
  const description = strip(j.content);
  // OR rather than AND, matching the in-app connectors: one company's board is
  // already a narrow list, and requiring every keyword drops the role you
  // wanted because the page said "Postgres" and not "PostgreSQL".
  const hay = `${j.title || ''} ${j.location?.name || ''} ${description}`.toLowerCase();
  if (kw.length && !kw.some(k => hay.includes(k))) continue;

  jobs.push({
    source: 'greenhouse',
    externalId: String(j.id),
    title: String(j.title || '').slice(0, 300),
    company: src.label,
    location: j.location?.name ? String(j.location.name).slice(0, 200) : null,
    remote: /remote/i.test(j.location?.name || ''),
    url: j.absolute_url || null,
    description: description ? description.slice(0, 40000) : null,
    postedAt: j.updated_at ? new Date(j.updated_at).toISOString() : null,
  });
}

// The ingest endpoint caps a request at 200; send the freshest.
jobs.sort((a, b) => String(b.postedAt || '').localeCompare(String(a.postedAt || '')));
return { json: { sourceId: src.id, label: src.label, error: null, jobs: jobs.slice(0, 200) } };

const src = $('Split Sources').item.json;
const res = $input.item.json;
const kw = (src.keywords || []).map(k => String(k).toLowerCase().trim()).filter(Boolean);

// Lever answers a bad token with {ok:false}; a good one with a bare array.
// The HTTP node wraps a top-level array under `data`.
const list = Array.isArray(res) ? res : (Array.isArray(res?.data) ? res.data : null);
if (!list) {
  const reason = res?.error || `No public Lever board called "${src.target}"`;
  return { json: { sourceId: src.id, label: src.label, error: String(reason).slice(0, 500), jobs: [] } };
}

const jobs = [];
for (const p of list) {
  const description = String(p.descriptionPlain || '').trim();
  const location = p.categories?.location || '';
  const hay = `${p.text || ''} ${location} ${description}`.toLowerCase();
  if (kw.length && !kw.some(k => hay.includes(k))) continue;

  jobs.push({
    source: 'lever',
    externalId: String(p.id),
    title: String(p.text || '').slice(0, 300),
    company: src.label,
    location: location ? String(location).slice(0, 200) : null,
    remote: /remote/i.test(`${location} ${p.workplaceType || ''}`),
    url: p.hostedUrl || null,
    description: description ? description.slice(0, 40000) : null,
    // Lever dates are epoch milliseconds, not ISO strings.
    postedAt: p.createdAt ? new Date(Number(p.createdAt)).toISOString() : null,
  });
}

jobs.sort((a, b) => String(b.postedAt || '').localeCompare(String(a.postedAt || '')));
return { json: { sourceId: src.id, label: src.label, error: null, jobs: jobs.slice(0, 200) } };

const src = $('Split Sources').item.json;
const cfg = $('Config').first().json;
const res = $input.item.json || {};
const result = (res.results || [])[0];

if (!result || result.success !== true) {
  // A page disallowed by robots.txt lands here, and that is a correct outcome
  // rather than a failure to work around. It is recorded against the source.
  const reason = result?.error_message || 'Crawl returned nothing — the page may be disallowed by robots.txt.';
  return { json: { sourceId: src.id, label: src.label, error: String(reason).slice(0, 500), jobs: [], skipModel: true } };
}

const md = typeof result.markdown === 'string' ? result.markdown : (result.markdown?.raw_markdown || '');

// Stable id from the URL, so the same posting is not re-imported every run.
// djb2 — short, deterministic, and it never has to be reversed.
function hash(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return h.toString(16);
}

const page = String(src.target);
const JOBBISH = /\/(jobs?|careers?|positions?|openings?|vacanc(y|ies))\//i;
const seen = new Set();
const found = [];

for (const m of md.matchAll(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g)) {
  const title = m[1].replace(/\s+/g, ' ').trim();
  const url = m[2].split('#')[0];
  if (!title || title.length < 3 || title.length > 200) continue;
  if (url === page || seen.has(url)) continue;
  // A job link either sits under a jobs/careers path or carries a long
  // numeric posting id. Nav links ("Pricing", "Login") match neither.
  if (!JOBBISH.test(url) && !/\/\d{6,}/.test(url)) continue;
  // Markdown images inside a link render as titles like "![](...)".
  if (/^!\[/.test(title)) continue;
  seen.add(url);
  found.push({
    title: title.replace(/\s*(Full-time|Part-time|Contract|Internship|Intern|Temporary)\s*$/i, '').trim(),
    url,
  });
  if (found.length >= 120) break;
}

const interests = (src.keywords || []).filter(Boolean).join(', ');
const listing = found.map((j, i) => `${i}. ${j.title}`).join('\n');

// Built here rather than in the HTTP node so the prompt and the list it
// describes cannot drift apart.
const ollamaBody = {
  model: cfg.ollamaModel,
  stream: false,
  keep_alive: '30m',
  options: { temperature: 0, num_ctx: 4096 },
  format: { type: 'object', properties: { keep: { type: 'array', items: { type: 'integer' } } }, required: ['keep'] },
  prompt: (interests
    ? `A job seeker is interested in: ${interests}.\n\nFrom the numbered list below, return the numbers of the roles plausibly relevant to those interests. Judge by meaning, not by exact words.`
    : 'From the numbered list below, return the numbers of every entry that is a real job opening rather than a navigation link.'
  ) + ' Return JSON only.\n\n' + listing,
};

return {
  json: {
    sourceId: src.id,
    label: src.label,
    pageUrl: page,
    candidates: found.map(j => ({ ...j, externalId: hash(j.url) })),
    ollamaBody,
    // Nothing to ask a model about, so the call is skipped rather than sent empty.
    skipModel: found.length === 0,
  },
};

const prev = $('Extract Job Links').item.json;

// The crawl already failed, or there was nothing to judge.
if (prev.error) {
  return { json: { sourceId: prev.sourceId, label: prev.label, error: prev.error, jobs: [] } };
}

const candidates = prev.candidates || [];
let keep = null;

try {
  const parsed = JSON.parse($input.item.json?.response ?? '{}');
  if (Array.isArray(parsed.keep)) keep = new Set(parsed.keep.map(Number));
} catch (e) {
  keep = null;
}

// A model that timed out, returned prose, or hallucinated indices must not
// silently empty the run. Falling back to every candidate errs toward showing
// too many jobs, which costs a scroll; the other direction loses the role.
const chosen = keep && keep.size
  ? candidates.filter((_, i) => keep.has(i))
  : candidates;

const jobs = chosen.map(c => ({
  source: 'careerpage',
  externalId: c.externalId,
  title: c.title.slice(0, 300),
  company: prev.label,
  location: null,
  remote: /remote/i.test(c.title),
  url: c.url,
  // Deliberately absent. The description lives on the posting's own page, and
  // fetching it would mean following links out of a listing — exactly the
  // bulk crawl this pipeline promises not to do. Open the job in JobOS and
  // use "fetch from URL" there, which is a single page on a user action.
  description: null,
  postedAt: null,
}));

return {
  json: {
    sourceId: prev.sourceId,
    label: prev.label,
    error: keep === null && candidates.length ? 'Relevance model unavailable — imported every candidate.' : null,
    jobs: jobs.slice(0, 200),
  },
};

// One row per source, so a board that has quietly 404'd for a month is
// visible here and in the JobOS UI rather than just missing from the results.
const rows = [];
let inserted = 0, updated = 0, failed = 0;

for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  let sent = {};
  try { sent = $('Send to JobOS').all()[i]?.json ?? {}; } catch (e) { sent = {}; }
  const label = res.label ?? sent.label ?? 'source ' + (i + 1);

  const ok = typeof res.inserted === 'number';
  if (!ok) failed++;
  inserted += res.inserted || 0;
  updated += res.updated || 0;

  rows.push({
    source: label,
    inserted: res.inserted ?? 0,
    updated: res.updated ?? 0,
    error: res.error ?? null,
  });
}

return [{ json: { ranAt: new Date().toISOString(), sources: rows.length, inserted, updated, failed, rows } }];
